    names[3] := "Scale2";
    names[4] := "ScaleRep";
    names[5] := "ScaleRep2";
    names[6] := "ApprScale";
    names[7] := "ApprScaleF";
    names[8] := "ApprScaleFR";
    names[9] := "COMPLEX_C";
    names[10] := "COMPLEX_DSHARP";
    names[11] := "COMPLEX_G";
    names[12] := "Muppets";

    repeat
        n := 0;
        // play each demo, demonstrate multitasking while tune playing
        repeat
            gfx_Cls();
            txt_MoveCursor(0,8);
            tune_Play( examples[n] );
            txt_Set(TEXT_PRINTDELAY, 0);
            putstr( names[n++] );
            repeat
                txt_Set(TEXT_PRINTDELAY, 50);
                txt_MoveCursor(0,0);
                putstr("Playing");
                pause(150);
                txt_MoveCursor(0,0);
